});
console.log("Page heading:", heading);

const tabId = 343605502;
const details = await browserjs(tabId, () => {
  const heading = document.querySelector('h1')?.innerText?.trim();
  const url = window.location.href;
  const articles = Array.from(document.querySelectorAll('article'));
  const parsed = [];
  const seen = new Set();

  for (const art of articles) {
    const title = art.querySelector('h2')?.innerText?.trim();
    if (!title || seen.has(title)) continue;
    seen.add(title);

    const lines = art.innerText.split('\n').map(s => s.trim()).filter(Boolean);
    parsed.push({
      title,
      text: lines.join(' | ')
    });
  }

  return { heading, url, sampleJobs: parsed.slice(0, 8) };
});

